mapper.select:
        select 
		       t.SEQ_NO as seqNo /* 流水号 */
		from TAX_VAT_SCHEDULE t


                AND t.SCH_ID = #{schId}


                AND t.ASSET_CLASSIFY = #{assetClassify}


                 AND t.CAPI_INCOME_FEATURE = #{capiIncomeFeature,jdbcType=VARCHAR}


                 AND  t.CAPI_INCOME_FEATURE IS NULL


                 AND t.INCOME_TYPE = #{incomeType}


	             AND t.EFF_DATE = to_date(#{effDate},'yyyy-mm-dd')



                 AND t.SEQ_NO != #{owner}
